#include <stdio.h>
#include <stdint.h>
#include <string.h>

#define TABLE_SIZE (1u << 21)
#define MASK (TABLE_SIZE - 1)

static uint64_t table[TABLE_SIZE];

static uint64_t make_key(int type, const char *s, int start, int len) {
    uint64_t code = 0;
    for (int i = 0; i < len; ++i)
        code = code * 27 + (uint64_t)(s[start + i] - 'a' + 1);
    return ((uint64_t)type << 60) | ((uint64_t)len << 54) | code;
}

static uint64_t hash_key(uint64_t x) {
    x += 0x9e3779b97f4a7c15ULL;
    x = (x ^ (x >> 30)) * 0xbf58476d1ce4e5b9ULL;
    x = (x ^ (x >> 27)) * 0x94d049bb133111ebULL;
    return x ^ (x >> 31);
}

static int contains(uint64_t key) {
    size_t pos = (size_t)hash_key(key) & MASK;
    while (table[pos] != 0) {
        if (table[pos] == key) return 1;
        pos = (pos + 1) & MASK;
    }
    return 0;
}

static void insert(uint64_t key) {
    size_t pos = (size_t)hash_key(key) & MASK;
    while (table[pos] != 0 && table[pos] != key)
        pos = (pos + 1) & MASK;
    table[pos] = key;
}

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) return 0;

    char s[32];

    for (int k = 0; k < n; ++k) {
        scanf("%31s", s);
        int len = (int)strlen(s);
        int invalid = 0;

        if (k > 0 && contains(make_key(0, s, 0, len)))
            invalid = 1;

        for (int split = 1; !invalid && split < len; ++split) {
            uint64_t suffix_key = make_key(1, s, 0, split);
            uint64_t prefix_key = make_key(2, s, split, len - split);
            if (contains(suffix_key) && contains(prefix_key))
                invalid = 1;
        }

        if (invalid) {
            puts(s);
            return 0;
        }

        for (int start = 0; start < len; ++start) {
            for (int sublen = 1; start + sublen <= len; ++sublen)
                insert(make_key(0, s, start, sublen));
        }

        for (int plen = 1; plen <= len; ++plen) {
            insert(make_key(2, s, 0, plen));
            insert(make_key(1, s, len - plen, plen));
        }
    }

    puts("ok");
    return 0;
}
